function noteMoveRace(array $moves):array{global $owner;$jobs=[];foreach($moves as [$note,$destination,$revision]){$pipes=[];$process=proc_open([PHP_BINARY,__DIR__.'/notes-visibility-child.php',(string)$owner,(string)$note,(string)$destination,(string)$revision],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__));check(is_resource($process),'Processo de movimentação');fclose($pipes[0]);$jobs[]=[$process,$pipes];}$results=[];foreach($jobs as [$process,$pipes]){$results[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($process)===0,'Concorrência sem erro: '.$error);}sort($results);return $results;}
$race=$notes->create($owner,'Mover uma vez',null);check(noteMoveRace([[$race,$sharedProject,1],[$race,$projectId,1]])===['conflict','ok'],'Apenas uma movimentação com mesma versão');check((int)appearanceRow($race)['revision']===2,'Versão avança uma vez');
$a=$notes->create($owner,'A',$sharedProject);$b=$notes->create($owner,'B',$projectId);check(noteMoveRace([[$a,$projectId,1],[$b,$sharedProject,1]])===['ok','ok'],'Movimentos cruzados sem deadlock');
